	eventVal, err = strconv.Atoi(args[2])
	if err != nil {
		return shim.Error("Expected integer value for event state change")
	}
	channelID := ""
	if len(args) == 4 {
		channelID = args[3]
	}

	if eventVal != 1 {
		fmt.Printf("Unexpected event. Doing nothing\n")
		return shim.Success(nil)
	}

	// Validate chainCodeToCall
	if !isAuthorizedChainCode(chainCodeToCall) {
		return shim.Error("Unauthorized chaincode")
	}

	f := "invoke"
